create extension if not exists vector;
create table documents (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, subject text not null, grade integer default 10, title text not null, file_url text not null, status text check (status in ('uploading','processing','indexed','failed')) default 'processing', created_at timestamptz default now());
create table document_chunks (id uuid primary key default gen_random_uuid(), document_id uuid references documents(id) on delete cascade, chapter_title text not null, page_number integer, content text not null, embedding vector(768), created_at timestamptz default now());
create index document_chunks_embedding_idx on document_chunks using hnsw (embedding vector_cosine_ops);
create table concepts (id uuid primary key default gen_random_uuid(), document_id uuid references documents(id) on delete cascade, subject text not null, chapter_title text not null, name text not null, description text, difficulty_tier integer default 1 check (difficulty_tier between 1 and 5), created_at timestamptz default now());
create table questions (id uuid primary key default gen_random_uuid(), concept_id uuid references concepts(id) on delete cascade, type text check (type in ('recall','conceptual','application','calculation')) not null, question text not null, ideal_answer text not null, rubric_criteria jsonb not null, difficulty integer default 1, created_at timestamptz default now());
create table student_attempts (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade, question_id uuid references questions(id) on delete cascade, student_answer text not null, is_correct boolean not null, score float not null check (score between 0 and 1), error_type text, gemini_feedback text, created_at timestamptz default now());
create table concept_mastery (user_id uuid references auth.users(id) on delete cascade, concept_id uuid references concepts(id) on delete cascade, mastery_score integer default 0 check (mastery_score between 0 and 100), interval_days integer default 1, ease_factor float default 2.5, next_review_at timestamptz default now(), updated_at timestamptz default now(), primary key (user_id, concept_id));
